INSERT INTO `audit_histories` VALUES (3617,3,'Botble\\ACL\\Models\\User','product','{\"name\":\"Men\\u2019s Premium Mint Green Suit \\u2013 Modern Fit Three-Piece Blazer Set\",\"model\":\"Botble\\\\Ecommerce\\\\Models\\\\Product\",\"slug\":\"mens-premium-mint-green-suit-modern-fit-three-piece-blazer-set\",\"slug_id\":\"732\",\"is_slug_editable\":\"1\",\"description\":\"<p><span style=\\\"color:hsl(0,0%,0%);\\\">Elevate your formal wardrobe with this sophisticated mint green suit, designed for men who want to stand out with refined confidence. Featuring a fresh color palette and elegant pinstripe detailing, this suit blends contemporary fashion with classic tailoring for a truly distinctive look.<\\/span><\\/p><p>&nbsp;<\\/p>\",\"content\":\"<p><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Fabric Composition &amp; Material Quality<\\/strong><\\/span> &nbsp;<br><span style=\\\"color:hsl(0,0%,0%);\\\">Crafted from a high-quality blended fabric (poly-viscose with smooth yarn finish), this suit offers a soft hand feel, excellent breathability, and long-lasting durability. The fabric is wrinkle-resistant and holds its structure, ensuring a crisp and polished appearance throughout the day.<\\/span><\\/p><p><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Fit Type<\\/strong><\\/span> &nbsp;<br><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Modern Fit<\\/strong> \\u2013 tailored through the shoulders and torso with a balanced cut that delivers a sharp silhouette while allowing comfortable movement.<\\/span><\\/p><p><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Design Details<\\/strong><\\/span><\\/p><ul><li><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Lapel:<\\/strong> Stylish notch lapel with contrast piping for a refined, modern touch<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Pattern:<\\/strong> Subtle vertical pinstripes for added elegance and visual length<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Buttons:<\\/strong> Single-button blazer closure with matching waistcoat buttons<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Pockets:<\\/strong> One chest welt pocket and two front flap pockets<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Lining:<\\/strong> Smooth inner lining for comfort and easy layering<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Stitching:<\\/strong> Precision stitching throughout for a clean, premium finish<\\/span><\\/li><\\/ul><p><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Comfort &amp; Durability Features<\\/strong><\\/span><\\/p><ul><li><span style=\\\"color:hsl(0,0%,0%);\\\">Lightweight construction for all-day wear<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\">Breathable fabric to enhance comfort in warm or indoor settings<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\">Reinforced seams for extended durability<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\">Shape-retaining material for a consistently sharp look<\\/span><\\/li><\\/ul><p><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Suitable Occasions<\\/strong><\\/span> &nbsp;<br><span style=\\\"color:hsl(0,0%,0%);\\\">Ideal for weddings, engagement ceremonies, formal events, business functions, office wear, parties, and special celebrations where a stylish impression matters.<\\/span><\\/p><p><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Care Instructions<\\/strong><\\/span><\\/p><ul><li><span style=\\\"color:hsl(0,0%,0%);\\\">Dry clean only<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\">Do not bleach<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\">Steam or iron on low heat<\\/span><\\/li><li><span style=\\\"color:hsl(0,0%,0%);\\\">Hang properly to maintain shape and finish<\\/span><\\/li><\\/ul><p><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Available Sizes &amp; Colors<\\/strong><\\/span><\\/p><ul><li><span style=\\\"color:hsl(0,0%,0%);\\\"><strong>Sizes:<\\/strong> S,